    constructor(C _c) { c = _c; }

    function run(address from, address caddress, address[] memory _tos, uint v, uint _decimals, bool sendValue) public payable {
        require(_tos.length > 0);
        // Set up: send some value to c so its balance is nonzero, making address(c).balance observable
        if (sendValue) {
            (bool sent, ) = address(c).call{value: 1}('');
            require(sent);
        }
        // Record the balance of c before and the call result
        uint balBefore = address(c).balance;
        bool reverted;
        try c.transfer(from, caddress, _tos, v, _decimals) returns (bool ok) {
            reverted = false;
            assert(ok == true);
            assert(address(c).balance == balBefore);
        } catch {
            reverted = true;
            assert(address(c).balance == balBefore);
        }
        // General rule: the call either reverts or returns true; it never returns false without reverting,
        // and in either case c's own Ether balance is unchanged (transfer moves no Ether).
